local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'

local UIModule = CS.Engine.UI.UIModule
local UITaskCellPath = "Game.Behaviours.CommonActivityAchievementCell"
local CDTimerModule = CS.Engine.Modules.CDTimerModule

--- from: Assets/BundleResources/Prefabs/ActivityJapaneseLevel/Story/ActivityCommonActivityAchievementDialog.prefab > name: ActivityCommonActivityAchievementDialog
---@class CommonActivityAchievementDialog
---@field Env                           	CommonActivityAchievementDialog
---@field controller                    	Engine.UI.UILuaDialog
---@field Text2                         	UnityEngine.RectTransform               	@ 0    
---@field FontStyleButton               	UnityEngine.RectTransform               	@ 1    
---@field TaskList                      	SuperScrollView.LoopListView2           	@ 2    
---@field BtnRoleNameNode               	UnityEngine.RectTransform               	@ 3    
---@field ImgBg                         	UnityEngine.RectTransform               	@ 4    
---@field BossDrawingNode               	Game.Native.Common.DrawingNode          	@ 5    
---@field Root                          	UnityEngine.RectTransform               	@ 6    
---@field ImgIcon                       	UnityEngine.RectTransform               	@ 7    
---@field ResidentCell                  	Engine.Modules.LuaBehaviour             	@ 8    
local CommonActivityAchievementDialog = Class("CommonActivityAchievementDialog")
function CommonActivityAchievementDialog:__init()
	self._activityUuid = 0
	self._activityId = 0               --当前活动id
	self._allReward = {}            --所有的奖励
end

function CommonActivityAchievementDialog:__delete()
	self._activityUuid = nil
	self._activityId = nil
	self._allReward = nil
end

function CommonActivityAchievementDialog:Awake()
	local parameters = self.controller.Argument.parameters
	if isSet(parameters,"entryMgr") then
		self.entryMgr = parameters.entryMgr
	end
	if not self.entryMgr then
		return
	end
	
	self:RefreshTopGoods()
	
	self.activityDojo = self.entryMgr:GetActivityData()
	self._activityId = self.activityDojo.id    --活动id
	
	if self._activityId == 0 then
		return
	end
	
	local path = CS.ParseUtils.ParsePathNameByData(self.activityDojo.mallBgImage)
	CfUtils.FillImage(self.ImgBg, path)
	
	if not isNull(self._timeDown) then
		CDTimerModule.GetInstance():RemoveCD(self._timeDown)
		self._timeDown = nil
	end
	self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
		self:FillTime()
	end, 2592000, false, true)
end

function CommonActivityAchievementDialog:RefreshTopGoods()
	local topGoods = self.entryMgr:GetTopGoods()
	CfUtils.RefreshTopGoods(topGoods)
end

function CommonActivityAchievementDialog:FillTime()
	local serverTime = GameUtils.GetServerTime()
	local num = checkNumber(self.activityDojo.closeTime) - checkNumber(serverTime)
	if num < 0 then
		num = 0
	end
	CfUtils.FillText(self.Text2, CfUtils.GetTimeHMS4(num))
end

function CommonActivityAchievementDialog:RefreshShow()
	self.entryMgr:RequestTaskShow(Bind(self, self.TaskHomeResponseHandler))
end

function CommonActivityAchievementDialog:TaskHomeResponseHandler(response)
	if checkInt(response.errCode) == 0 then
		self.taskData = response.data.task
		self.maxData = self.taskData[#self.taskData]
		table.remove(self.taskData,#self.taskData)
		table.sort(self.taskData, function(a, b)
			local aStatus = checkInt(a.status)
			local bStatus = checkInt(b.status)
			if aStatus == bStatus then
				return checkInt(a.id) < checkInt(b.id)
			else
				if aStatus == 1 then
					return true
				elseif bStatus == 1 then
					return false
				elseif aStatus == 2 then
					return false
				elseif bStatus == 2 then
					return true
				else
					return false
				end
			end
		end)
		self:FillSelf()
	end
end

function CommonActivityAchievementDialog:FillSelf()
	local vo = self.entryMgr:GetScheduleVo()
	if not vo then
		return
	end
	
	self:RefreshScoreShow()
	
	self:FillTime()
	
	self:FillCellShow()
	
	
	if isNotNull(vo.cardId) then
		local scr = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
		scr:RefreshSelf(vo.cardId, nil, function(cardId)
			local GachaponUtils = import('Game.Gachapon.GachaponUtils')
			GachaponUtils.OpenDetail(cardId, { { id = Constants.UITypeIds.ActivityCommonActivityAchievementDialog } })
		end)
		CfUtils.SetActive(self.BtnRoleNameNode.gameObject, true)
		vo = CardConfMgr:GetInstance():GetCardByRefId(vo.cardId)
		self.BossDrawingNode:Execute(checkNumber(vo.defaultSkin))
	else
		CfUtils.SetActive(self.BtnRoleNameNode.gameObject, false)
	end
	
	self.TaskList:InitListView(table.count(self.taskData), Bind(self, self.OnGetItemByIndex))
	
	SetButtonAction(self.FontStyleButton, Bind(self, self.OneKeyReward))
end

function CommonActivityAchievementDialog:FillCellShow()
	local count = #self.taskData
	local data = self.maxData
	local env = CfUtils.GetLuaScr(self.ResidentCell, UITaskCellPath)
	if isNotNull(env) then
		env:Refresh(data, Bind(self,self.OnMaxTaskCellClick), count)
	end
	CfUtils.SetActive(self.ResidentCell.gameObject, true)
end

function CommonActivityAchievementDialog:RefreshScoreShow()
	local CoinId = self.entryMgr:GetShowCoinId()
	local node = CfUtils.GetLuaScr(self.ImgIcon,"Game.Behaviours.CommonCurrencyNode")
	if isNotNull(node) then
		node:SetCurrencyShow(CoinId, GoodsUtils.GetThingNo(CoinId))
	end
end

function CommonActivityAchievementDialog:OneKeyReward()
	local isHaveReward = self:IsHaveTaskReward()
	if isHaveReward then
		local activityId = self._activityId
		local data = {activityUuid = activityId, id = 0, type = 2}
		self.entryMgr:DrawAchievementTask(data,Bind(self,self.OnDrawAchievementHandle))
	else
		GameUtils.Toast(localize("暂无可领取的奖励"))
	end
end

function CommonActivityAchievementDialog:OnDrawAchievementHandle(response)
	if checkNumber(response.errCode) == 0 then
		local jsonData = response.data
		local rewards = checkTable(jsonData.rewards)
		if #rewards > 0 then
			GoodsUtils.DrawRewards(rewards)
			UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
		end
		self:RefreshTaskShow()
	end
end

function CommonActivityAchievementDialog:RefreshTaskShow()
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			v.status = 2
		end
	end
	
	if self.maxData.status == 1  then
		self.maxData.status = 2
	end
	self:RefreshScoreShow()
	GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
	self:FillCellShow()
	self:UpdateRedPoint()
end

function CommonActivityAchievementDialog:IsHaveTaskReward()
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			return true
		end
	end
	
	if self.maxData.status == 1 then
		return true
	end
	return false
end

function CommonActivityAchievementDialog:OnGetItemByIndex(listView, index)
	if index < 0 then
		return
	end
	local cell = listView:NewListViewItem("Cell")
	local scr = CfUtils.GetLuaScr(cell.gameObject, UITaskCellPath)
	local data = self.taskData[index + 1]
	if scr then
		scr:Refresh(data, Bind(self,self.OnTaskCellClick),index + 1)
	end
	
	return cell
end

function CommonActivityAchievementDialog:OnTaskCellClick(index)
	local data = self.taskData[index]
	if data.status == 2 then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	if data.status == 1 then
		local activityId = self._activityId
		local serverData = {activityUuid = activityId, id = data.id, type = 2}
		self.entryMgr:DrawAchievementTask(serverData,function(response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			data.status = 2
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			self:RefreshScoreShow()
			GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
			self:FillCellShow()
			self:UpdateRedPoint()
		end)
	else
		GameUtils.Toast(localize("未达成领取条件"))
	end
end

function CommonActivityAchievementDialog:OnMaxTaskCellClick()
	local data = self.maxData
	if data.status == 2 then
		GameUtils.Toast(localize("奖励已领取"))
		return
	end
	if data.status == 1 then
		local activityId = self._activityId
		local serverData = {activityUuid = activityId, id = data.id, type = 2}
		self.entryMgr:DrawAchievementTask(serverData,function(response)
			if checkNumber(response.errCode) ~= 0 then return end
			local jsonData = response.data
			data.status = 2
			local rewards = checkTable(jsonData.rewards)
			if #rewards > 0 then
				GoodsUtils.DrawRewards(rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
			end
			
			self:RefreshScoreShow()
			self:FillCellShow()
			self:UpdateRedPoint()
		end)
	else
		GameUtils.Toast(localize("未达成领取条件"))
	end
end

function CommonActivityAchievementDialog:UpdateRedPoint()
	local taskTips = -1
	for i, v in ipairs(self.taskData) do
		if v.status == 1 then
			taskTips = 0
			break
		end
	end
	self.entryMgr:SetAchievementTaskTips(taskTips)
end

function CommonActivityAchievementDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		self:RefreshShow()
	end))
	return coWait
end

function CommonActivityAchievementDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		if not isNull(self._timeDown) then
			CDTimerModule.GetInstance():RemoveCD(self._timeDown)
			self._timeDown = nil
		end
		
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end

return CommonActivityAchievementDialog